import json,re,html
s=json.load(open('source.json')); refs=json.load(open('reference-targets.json')); out=[]
def txt(x):return html.unescape(re.sub('<[^>]+>','',x))
def effect(kind,mid,b,a,desc,pop,transition,unit='legal_duty'):
 return dict(kind=kind,measure_id=mid,description=desc,before=b,after=a,unit=unit,affected_population=pop,conditions_and_transition=transition,replacement_or_new_burdens='Aucune formalité de remplacement ; les garanties et contrôles autonomes demeurent.',source_quote=b,proposed_quote=a)
def base(i):
 a=s[i];return {k:a[k] for k in ['code_id','source_id','source_sha256','number']}
def finish(i,p,reason,notes,effects,removed,assessment,classification='material_reduction'):
 a=base(i); a.update(proposed_xml=p,reason=reason,review_notes=notes,status='rewrite_draft',change_type='normative_reduction',reform_policy_id='editorial_direction_2026_10_19',removed_provisions=removed,substantive_impact=dict(version=1,classification=classification,assessment=assessment,scope_limitations='Les effets sont limités aux clauses expressément modifiées et à leurs transitions. Aucun solde budgétaire ou de complexité de l’ensemble des codes n’est établi ; les textes extérieurs signalés ne sont pas réécrits ici.',new_burdens_review='Aucune charge nouvelle identifiée : aucun registre, justificatif, délai, autorisation ou déclaration ne remplace les exigences supprimées. Les obligations autonomes conservées préexistent.',effects=effects),reference_checks=[]);out.append(a);return a
p=s[0]['source_xml']; effects=[]
b="Les actionnaires sont réunis en assemblée primaire à l'initiative du conseil d'administration au moins une fois par an et au minimum un mois avant la réunion de l'assemblée générale ordinaire."
a="Les actionnaires sont réunis en assemblée primaire à l'initiative du conseil d'administration au moins une fois par an, avant la réunion de l'assemblée générale ordinaire, sans intervalle minimal imposé entre ces deux réunions."
p=p.replace(b,a);effects.append(effect('obligation_removed','hlm-assemblees-primaires-fin-intervalle',b,a,'Suppression du mois minimal entre assemblée primaire et assemblée générale ; convocation préalable de quinze jours maintenue.','Sociétés coopératives de location-attribution dotées d’unités coopératives.','Réunions postérieures à l’entrée en vigueur ; convocations déjà faites valables.'))
b="Dans le mois suivant celui au cours duquel s'est tenue l'assemblée générale réunie en application de l'article L. 225-100 du code de commerce, la société adresse au préfet du département de son siège, à la Caisse des dépôts et consignations et au ministre chargé du logement l'ensemble des documents comptables et les rapports présentés à l'assemblée générale des actionnaires, ainsi que le compte rendu de celle-ci."
a="La société n'est pas tenue de transmettre systématiquement au préfet, à la Caisse des dépôts et consignations et au ministre chargé du logement les documents comptables, rapports et comptes rendus de l'assemblée générale sur le fondement de la présente clause."
p=p.replace(b,a).replace("En cas de report de l'assemblée générale des actionnaires, la décision de justice accordant un délai supplémentaire doit être adressée dans les mêmes conditions.","La transmission systématique de la décision de justice reportant l'assemblée générale n'est pas requise. Les obligations de tenue, de conservation et de publicité des comptes ainsi que les communications légalement requises pour les contrôles ou les financements demeurent applicables.")
effects.append(effect('obligation_removed','hlm-location-attribution-envois-annuels',b,a,'Suppression des envois systématiques de la clause 12, y compris de la décision de report.','Coopératives de location-attribution.','Envois non encore effectués lors de l’entrée en vigueur, sans rattrapage.'))
p += "<p>Les modifications des clauses 11 et 12 s'appliquent à compter de l'entrée en vigueur du décret portant modification de la présente annexe. Les convocations déjà effectuées restent valables. Aucune transmission ni régularisation des envois supprimés par la clause 12 n'est exigée après cette date, même pour un exercice antérieur. Les documents déjà transmis, les contrats valablement conclus, les droits acquis et les recours relatifs aux actes antérieurs demeurent préservés.</p>"
a=finish(0,p,'Réforme de fond limitée aux charges procédurales : retrait du mois séparant obligatoirement les assemblées et des envois systématiques de la clause 12. Les règles de capital, cession, gouvernance, droits coopératifs et affectation sociale restent intégrales. Les agréments de cession et de retrait protègent ici la relation entre actionnariat et location-attribution ; ils ne sont pas assimilés à un agrément administratif inutile.',"Les seize clauses sont conservées. Aucun CDD, préavis de licenciement ou calcul d’indemnité de rupture ne figure dans cette source. La clause 7 vise R421-10 entier, dont la proposition conserve gratuité, facultés d’indemnisation, formation et régime des agents publics ; elle ne crée pas elle-même un droit d’absence. La contradiction entre L423-13 officiel encore fourni et la suppression annoncée pour les conseils doit être résolue dans L423-13, hors de ce lot. Clause 16 maintenue : R422-37 proposé subordonne encore le bénéfice HLM à l’approbation des statuts, laquelle ne doit pas être entravée. Les références préexistantes au décret 67-236, à L232-12 pour le bénéfice distribuable et aux alinéas 3 à 5 de la clause 5 appellent concordance extérieure : elles ne sont pas présentées comme corrigées. Les blancs de dénomination, siège et capital sont ceux du modèle officiel, non des passages omis.",effects,['Intervalle obligatoire d’un mois entre assemblée primaire et assemblée générale ordinaire.','Envoi systématique des comptes, rapports et procès-verbal à trois destinataires et de la décision judiciaire de report.'],'Deux charges procédurales effectivement retirées ; aucun taux fiscal, plafond de dividende ou droit coopératif n’est réduit.')
a['benefit_review']='Les dispenses d’agrément des cessions par succession, liquidation de communauté et au conjoint, ascendant ou descendant restent entières, sans condition fiscale nouvelle. Sont conservés la dérogation au prix de cession, le prix minimal de rachat et l’agrément tacite après trois mois, les plafonds de vote de 35 % et 49 %, l’absence de quorum, les possibilités de dividende (livret majoré de 1,5 point), de transfert de réserves et les exceptions de L423-5. Le renvoi à R421-10 conserve les facultés de remboursement et de formation et le régime public. Ces avantages demeurent ouverts aux situations futures recevables ; la suppression des transmissions ne conditionne aucun avantage à un nouveau dépôt.'
checks=["L1234-1 règle le préavis du salarié licencié et sa transition selon la date du contrat ; aucune clause de cette annexe ne le vise. Le mandat gratuit d’administrateur n’est pas un contrat de travail. Ni ancienneté ni notification de rupture ne doivent être ajoutées aux statuts.","L1221-2 proposé impose la durée indéterminée aux nouveaux emplois privés. Les contrats de location-attribution de la clause 3 sont des contrats de logement, et leur terme ne constitue pas un CDD ; leur conservation est donc nécessaire et ne contourne pas le contrat unique.","L1234-9 proposé vise l’indemnité ordinaire patronale, seuil d’un an au terme effectif préavis compris puis 0,20 mois sur toute l’ancienneté et plafond de six mois. Aucun renvoi à cette indemnité ne figure ici ; remboursement du capital et indemnités de mandat restent des régimes distincts.","L423-13 officiel traite du temps d’absence et de l’indemnisation des séances, sans ancienneté ni notification de rupture. La coordination annonce la suppression du volet conseils mais le fichier ne fournit aucune proposition de cet article : cette divergence est signalée, sans appliquer le barème de licenciement à une perte de rémunération de mandat.","La clause 7 renvoie à R421-10 pour la gratuité et ses exceptions. Sa proposition maintient indemnités facultatives des conseils, frais, trois jours de formation et autorisations d’absence des agents publics, et l’indemnité obligatoire de commission. Ces droits ne dépendent pas du seuil d’un an ni du préavis de quinze jours ; le renvoi entier demeure utile."]
for k,t in zip(refs['requirements'][a['code_id']+'|'+a['source_id']],checks):a['reference_checks'].append(dict(target_key=k,view_sha256=refs['targets'][k]['view_sha256'],assessment=t))
# Ancien régime, conservé explicitement.
p=s[1]['source_xml'];b='Les statuts de la société sont transmis au préfet du département du siège de la société après chaque modification.';a="Les modifications des statuts ne donnent pas lieu à une transmission systématique au préfet sur le seul fondement de la présente clause. Les demandes d'approbation ou d'agrément exigées par une disposition distincte, la publicité légale et les communications requises dans le cadre des contrôles demeurent applicables."
p=p.replace(b,a)
p+="<p>Les renvois des présentes clauses aux articles L. 423-1-1 à L. 423-1-3 et R. 423-85 à R. 423-92 s'entendent dans leurs rédactions maintenues applicables aux sociétés anonymes déjà agréées à la date de promulgation de la loi n° 2018-1021 du 23 novembre 2018. La dispense de transmission de la clause 11 s'applique aux envois non encore effectués à l'entrée en vigueur du décret portant modification de la présente annexe, sans transmission de rattrapage. Les agréments, contrats, exonérations et droits antérieurs sont préservés ; les opérations futures éligibles continuent à bénéficier des avantages du régime maintenu.</p>"
finish(1,p,'Suppression de l’envoi systématique des statuts modifiés au préfet, sans déclaration de remplacement. Coordination temporelle expresse des renvois de ce modèle ancien : il ne doit pas être appliqué comme modèle du régime ELAN nouveau. Les compétences, garanties de rachat, représentation locative et conditions d’accès aux missions sont intégralement maintenues.',"Les onze clauses et les deux versions de la clause 7 sont reproduites. Le V de l’article 81 de la loi 2018-1021 et l’article 2 du décret 2019-911, reproduits dans les notes du corpus de L423-1-2 et R423-87 à 89, maintiennent le régime ancien. Les numéros R423-86/87/88/89 ont été réutilisés : les renvois désignent leurs versions anciennes, non les articles actuels relatifs aux statuts, à la compétence nationale ou au retrait d’agrément. Le corpus fourni ne reproduit pas intégralement ces versions anciennes : leur concordance détaillée demeure à contrôler, sans prétention d’achèvement de cette filiation. L’exonération de L443-14, les droits de rachat et les exonérations fiscales du régime maintenu restent ouverts. Le décret commercial 67-236 et le renvoi de forme à L422-5 à 11 appellent concordance ; aucun nouveau contenu extérieur n’est inventé.",[effect('obligation_removed','hlm-statuts-fin-transmissions-systematiques',b,a,'Suppression de l’envoi autonome des modifications statutaires ; procédures distinctes conservées.','Sociétés anonymes de coordination relevant du régime ancien maintenu.','Envois encore non effectués à l’entrée en vigueur du décret.')],['Transmission systématique de chaque modification statutaire au préfet, hors demandes légalement distinctes.'],'Un circuit de transmission supprimé dans le régime ancien ; aucune extension artificielle des réformes réservées aux nouvelles sociétés.')
# Nouveau régime : coordination des réformes déjà présentes au corpus.
p=s[2]['source_xml'];eff=[];removed=[]
pairs=[("-d'élaborer le cadre stratégique patrimonial et le cadre stratégique d'utilité sociale commun mentionnés à l'article L. 423-1-1 du code de la construction et de l'habitation ;","-à la demande des associés concernés, d'élaborer et d'actualiser facultativement le cadre stratégique patrimonial et le cadre stratégique d'utilité sociale commun mentionnés à l'article L. 423-1-1 du code de la construction et de l'habitation ;"),('-de définir la politique technique des associés ;','-à la demande des associés concernés, de définir facultativement une politique technique commune, sans dispense des règles techniques, de sécurité, de salubrité et d’accessibilité ;'),("-de définir et mettre en œuvre une politique d'achat des biens et services, hors investissements immobiliers, nécessaires à l'exercice par les associés de leurs activités ;","-à la demande des associés concernés, de définir et mettre en œuvre facultativement une politique d'achat des biens et services, hors investissements immobiliers, nécessaires à l'exercice de leurs activités ;"),('-de développer une unité identitaire des associés et de définir des moyens communs de communication, notamment par la création ou la licence de marques et de signes distinctifs ;','-à la demande des associés concernés, de développer facultativement une identité commune et des moyens communs de communication, notamment par la création ou la licence de marques et de signes distinctifs ;')]
for b,a in pairs:p=p.replace(b,a)
eff.append(effect('coordination','hlm-coordination-politiques-facultatives',pairs[0][0],pairs[0][1],'Coordination des quatre politiques et cadres devenus facultatifs dans L423-1-2.','Sociétés de coordination du régime de 2018.','Entrée en vigueur de la réforme de L423-1-2 ; cadres utilisables et engagements valables conservés.'));removed.append('Caractère obligatoire des quatre cadres et politiques communes, en coordination avec L423-1-2 proposé.')
b='Les prêts et avances consentis sont soumis au régime de déclaration mentionné aux articles L. 423-15 et L. 423-16 du code de la construction et de l’habitation ;'.replace('l’habitation',"l'habitation")
a="Les prêts et avances autorisés par les articles L. 423-15 et L. 423-16 et consentis entre la société et ses associés ou entre ses associés sont dispensés de déclaration préalable aux ministres et de délai d'opposition dans les conditions de l'article L. 423-1-2. Les autres conditions de ces financements et l'information de la Caisse de garantie du logement locatif social lorsqu'elle est requise demeurent applicables, sans déclaration ni autorisation de remplacement ;"
assert b in p;p=p.replace(b,a);eff.append(effect('coordination','hlm-coordination-fin-declaration-prets',b,a,'Coordination de la dispense préalable des financements intragroupe.','Société et associés, pour les seuls prêts et avances autorisés.','Champ et transition de L423-1-2 ; oppositions déjà prises non annulées.'));removed.append('Déclaration préalable et délai d’opposition des prêts et avances intragroupe couverts par la dispense législative.')
b="Enfin, la société de coordination a également pour objet, après y avoir été spécialement agréée dans les conditions fixées à l'article L. 422-5 du code de la construction et de l'habitation après accord de la ou des collectivités territoriales concernées ou, le cas échéant, de leurs groupements, d'exercer certaines des compétences énumérées au quatrième alinéa et aux alinéas suivants de l'article L. 422-2 du même code et qui sont communes aux organismes publics et aux sociétés anonymes d'habitations à loyer modéré. (2)"
a="Enfin, la société de coordination peut également avoir pour objet d'exercer certaines des compétences énumérées au quatrième alinéa et aux alinéas suivants de l'article L. 422-2 du code de la construction et de l'habitation et qui sont communes aux organismes publics et aux sociétés anonymes d'habitations à loyer modéré. L'agrément initial suffit, sans agrément spécial ni accord préalable des collectivités territoriales ou de leurs groupements, sous réserve des conditions de fond applicables à ces compétences. (2)"
assert b in p;p=p.replace(b,a);eff.append(effect('coordination','hlm-coordination-fin-agrement-special',b,a,'Retrait statutaire du second agrément et de l’accord local déjà supprimés par L423-1-2 proposé.','Sociétés relevant du régime de 2018, existantes et nouvelles.','Demandes pendantes sans objet à l’entrée en vigueur de la réforme législative.'));removed.append('Agrément spécial et accord local pour l’extension des compétences, en coordination avec le régime législatif proposé.')
b="sous réserve de l'approbation administrative donnée dans les conditions prévues à l'article R. 422-17 du même code et que l'attributaire s'engage à utiliser les fonds attribués à des investissements conformes au service d'intérêt économique général du logement social."
a="à condition que l'attributaire s'engage à utiliser les fonds attribués à des investissements conformes au service d'intérêt économique général du logement social. Aucune approbation administrative de cette attribution n'est requise ; les contrôles légaux de son affectation demeurent applicables."
assert b in p;p=p.replace(b,a);eff.append(effect('coordination','hlm-affectation-actif-fin-approbation',b,a,'Coordination de L422-11 et de l’abrogation proposée de R422-17 ; affectation SIEG maintenue.','Sociétés de coordination en liquidation.','Décisions d’attribution postérieures à la suppression législative, même liquidation déjà ouverte.'));removed.append('Approbation administrative de l’affectation légale de l’actif, déjà supprimée dans L422-11 proposé.')
b='Les statuts de la société sont transmis au ministre chargé du logement et au préfet du département du siège de la société après chaque modification.'
a="Les modifications des statuts ne donnent pas lieu à une transmission systématique au ministre chargé du logement ou au préfet sur le seul fondement de la présente clause. Les demandes d'agrément initial, la publicité légale et les communications requises dans le cadre des contrôles demeurent applicables."
assert b in p;p=p.replace(b,a);eff.append(effect('obligation_removed','hlm-statuts-fin-transmissions-systematiques',b,a,'Retrait des envois statutaires systématiques, au-delà des seules modifications de capital ou d’actionnariat visées par R423-87 proposé.','Sociétés de coordination régies par le modèle de 2022.','Envois non encore effectués à l’entrée en vigueur, sans rattrapage.'));removed.append('Transmission systématique des statuts modifiés au ministre et au préfet, sans dépôt de remplacement.')
p+="<p>Les dispositions modifiées de la clause 4 s'appliquent à compter de l'entrée en vigueur de la réforme de l'article L. 423-1-2, dans son champ et selon ses transitions. Les cadres déjà élaborés restent utilisables ; les plans stratégiques de patrimoine, conventions d'utilité sociale et engagements contractuels valablement formés conservent leur régime propre. Le renvoi à la soutenabilité financière ne permet pas d'imposer une cession ou une fusion supprimée par cette réforme. Les contrats conclus et transferts déjà réalisés ne sont pas défaits. Les demandes d'agrément spécial ou d'accord local pendantes deviennent sans objet. La dispense de déclaration des financements couvre les déclarations non encore déposées, même pour les financements convenus antérieurement, sans annuler les décisions d'opposition déjà prises. La dispense d'approbation de la clause 12 s'applique aux décisions d'attribution prises à compter de l'entrée en vigueur de la suppression de l'approbation prévue à l'article L. 422-11, y compris dans une liquidation déjà ouverte ; les attributions antérieures gardent leur régime. La dispense de transmission de la clause 13 s'applique aux envois non encore effectués à l'entrée en vigueur du décret portant modification de la présente annexe, sans rattrapage. Les droits des tiers, créances antérieures, recours et exonérations, y compris pour les opérations futures éligibles, sont préservés.</p>"
finish(2,p,'Nouveau corps complet coordonnant les suppressions déjà retenues dans L423-1-2, R423-85, L422-11 et R422-17, et retirant les envois systématiques de statuts modifiés. Les clauses 1 à 13, les deux formes de conseil et les quatre notes restent présentes. Aucun droit de vote, seuil de capital, protection locative, dividende autorisé ou affectation SIEG n’est supprimé.',"Lecture des textes et propositions du corpus L423-1-2, R423-85 à 89, L422-11 et R422-17 : les propositions ne sont pas le droit en vigueur. L’annexe de 2022 autorise une détention de 50 % par certaines sociétés locales, absente de la version de L423-1-2 fournie au corpus : discordance préexistante signalée, avantage maintenu, sans prétendre corriger le texte législatif. Les renvois relatifs aux élections et aux organes sont conservés, non transformés en règles de contrat privé. Les cotisations de fonctionnement et comptes combinés subsistent pour financer et contrôler les missions maintenues ; ce ne sont ni une CVAE ni une contribution additionnelle d’IS. Le plafond de dividende livret A majoré de 1,5 point ne constitue pas un taux d’IS. La dispense d’approbation exige l’entrée en vigueur coordonnée de L422-11 et R422-17. Les champs vierges de capital et les options à rayer sont ceux du modèle officiel ; aucune section n’est remplacée par ces champs.",eff,removed,'Réductions statutaires effectives : quatre coordinations de mesures législatives déjà proposées et suppression additionnelle des envois de statuts. Les coordinations ne sont pas comptées comme de nouvelles taxes ou procédures générales supprimées.')
for a,src in zip(out,s):
 for e in a['substantive_impact']['effects']:
  assert e['source_quote'] in txt(src['source_xml']), e['measure_id']
  assert e['proposed_quote'] in txt(a['proposed_xml']), e['measure_id']
 assert len(a['reference_checks'])==len(refs['requirements'][a['code_id']+'|'+a['source_id']])
json.dump(out,open('answer.json','w'),ensure_ascii=False,indent=2)
print('Written',len(out),'articles')
